) ENGINE=InnoDB AUTO_INCREMENT=8163 DEFAULT CHARSET=utf8;

INSERT INTO manager_exam VALUES("412","ข้อใดคือความหมายของเทคโนโลยีสารสนเทศ","","หมายถึงฮาร์ดแวร์","","เทคโนโลยีที่ใช้จัดการสารสนเทศ","","เทคโนโลยีที่ใช้เก็บข้อมูลอย่างเดียว","","เทคโนโลยีที่ใช้รวบรวมข้อมูล","","2","144","ไม่มีข้อถูก",""),
